INSERT INTO qa VALUES ('qa-ebb683674f53','cadw','Cadw / Welsh Government','welsh-government-and-cadw-email-correspondence-catalogue-part-3#t9','2026-10-10','Any recorded information identifying whether files in those series that would have related to Great House Farm / Tŷ Mawr / Llandough-juxta-Penarth, or to the companies Western Ground Rents Ltd or BP Properties Ltd, were destroyed, transferred or retained, and if destroyed the date and authority.
